Okay, the new `registerProvider/configureProvider` on `.flue/app.ts`  introduced in v0.4/0.5 resolves the thing.

Just putting this here for others. At `.flue/app.ts`:

```ts
// .flue/app.ts

import { configureProvider, flue } from "@flue/sdk/app";
import { refreshOpenAICodexToken } from "@mariozechner/pi-ai/oauth";

const flueApp = flue();

export default {
  async fetch(
    request: Request,
    env: Parameters<typeof flueApp.fetch>[1],
    ctx: Parameters<typeof flueApp.fetch>[2],
  ): Promise<Response>

    // Optionally, expose an endpoint to for the current status
    // if (url.pathname === "/some-endpoint/openai-codex/status") {
    //   const auth = await readAuth();
    //   return Response.json({
    //     configured: Boolean(auth?.access && auth?.refresh),
    //     expires: auth?.expires,
    //     expiresAt: auth?.expires
    //       ? new Date(auth.expires).toISOString()
    //       : undefined,
    //     lastRefresh: auth?.lastRefresh,
    //   });
    // }

    // We run `configureProvider` _INSIDE_ the fetch request
    // because otherwise the auth could hold stale access token.
    await configureOpenAICodexForRequest();

    return flueApp.fetch(req, env, ctx);
  }
}

async function configureOpenAICodexForRequest(): Promise<void> {
  const auth = await resolveOpenAICodexAuth();

  configureProvider("openai-codex", {
    baseUrl: OPENAI_CODEX_BASE_URL,
    apiKey: auth?.access,
  });
}

const storedAuthSchema = v.object({
  access: v.string(),
  refresh: v.string(),
  expires: v.number(),
  accountId: v.string(),
  lastRefresh: v.string(),
});

type StoredAuth = v.InferOutput<typeof storedAuthSchema>;

// Read from filesystem auth file or from db or wherever.
async function readAuth(): Promise<StoredAuth | undefined> {
  try {
    const raw = await readFile(AUTH_PATH, "utf8");
    return v.parse(storedAuthSchema, JSON.parse(raw));
  } catch (error) {
    if ((error as any).code === "ENOENT") {
      return undefined;
    }
    throw error;
  }
}

async function resolveOpenAiCodexAuth() {
  const auth = await readAuth();

    if (!auth?.access || !auth?.refresh) {
      return undefined;
    }

    if (Date.now() < auth.expires - REFRESH_SKEW_MS) {
      return auth;
    }

    // use `pi-ai` util for OpenAI Codex OAuth refreshing
    const refreshed = await refreshOpenAICodexToken(auth.refresh);
    const next = {
      ...auth,
      ...refreshed,
      lastRefresh: new Date().toISOString(),
    } satisfies StoredAuth;

    await saveAuth(next);

    return next;
}
```

i think the clean split is model identity vs dispatch:

- `cloudflare-workers-ai/@cf/...` = canonical model/catalog identity
- Cloudflare binding = target/runtime transport override for that provider
- `cloudflare/@cf/...` = migration alias, not the long-term concept

i’d probably avoid putting the transport implementation directly into `configureProvider()` if possible. that API still reads like provider settings to me: `apiKey`, `baseUrl`, `headers`, `storeResponses`.

a sibling transport registry feels cleaner, and can stay mostly runtime/internal until another target needs it:

```ts
configureProvider('cloudflare-workers-ai', { headers, apiKey });

configureTransport(
  'cloudflare-workers-ai',
  cloudflareWorkersAiBindingTransport(env.AI),
);
```

or even generated-entry-only first:

```ts
configureFlueRuntime({
  providerTransports: {
    'cloudflare-workers-ai': workersAiBindingTransport(env.AI),
  },
});
